// Guard: empty/missing message goes straight to error path, never hits the LLM
const f = $input.first().json;
if (!f.message || typeof f.message !== 'string' || f.message.trim().length === 0) {
  return [{ json: { ...f, skip_llm: true, validation_status: 'invalid', error: 'missing or empty message field' } }];
}
return [{ json: { ...f, skip_llm: false } }];

