// 04 Parse + validate - never throws, always returns a structured result
const item = $input.first();
const fields = $('02 Set fields').first().json;
const raw = item.json;

// API/model failure or timeout (continueOnFail put the error here)
if (item.error || raw.error) {
  return [{ json: {
    request_id: fields.request_id, received_at: fields.received_at, message: fields.message,
    validation_status: 'invalid', error: 'API/model failure or timeout: ' + JSON.stringify(item.error || raw.error)
  }}];
}

let modelText;
try { modelText = raw.choices[0].message.content; }
catch (e) { return [{ json: { request_id: fields.request_id, received_at: fields.received_at, message: fields.message, validation_status: 'invalid', error: 'Unexpected API response shape' } }]; }

let parsed;
try { parsed = JSON.parse(modelText); }
catch (e) { return [{ json: { request_id: fields.request_id, received_at: fields.received_at, message: fields.message, validation_status: 'invalid', error: 'Invalid JSON from model: ' + modelText } }]; }

const requiredKeys = ['category','confidence','summary','risk','needs_human'];
for (const k of requiredKeys) {
  if (!(k in parsed)) return [{ json: { request_id: fields.request_id, received_at: fields.received_at, message: fields.message, validation_status: 'invalid', error: 'Missing required key: ' + k } }];
}

const allowedCategories = ['billing','technical','account','spam','other'];
const allowedRisk = ['low','medium','high'];

if (!allowedCategories.includes(parsed.category)) return [{ json: { request_id: fields.request_id, received_at: fields.received_at, message: fields.message, validation_status: 'invalid', error: 'Unknown category: ' + parsed.category } }];
if (typeof parsed.confidence !== 'number' || parsed.confidence < 0 || parsed.confidence > 1) return [{ json: { request_id: fields.request_id, received_at: fields.received_at, message: fields.message, validation_status: 'invalid', error: 'confidence out of range: ' + parsed.confidence } }];
if (!parsed.summary) return [{ json: { request_id: fields.request_id, received_at: fields.received_at, message: fields.message, validation_status: 'invalid', error: 'summary missing' } }];
if (!allowedRisk.includes(parsed.risk)) return [{ json: { request_id: fields.request_id, received_at: fields.received_at, message: fields.message, validation_status: 'invalid', error: 'Unknown risk value: ' + parsed.risk } }];

// Safety overrides (hard-coded, not left to the model)
if (parsed.risk === 'high') parsed.needs_human = true;
if (parsed.confidence < 0.6) parsed.needs_human = true;

return [{ json: {
  request_id: fields.request_id, received_at: fields.received_at, message: fields.message,
  category: parsed.category, confidence: parsed.confidence, summary: parsed.summary,
  risk: parsed.risk, needs_human: parsed.needs_human, validation_status: 'valid', error: null
}}];
